// 1. Pega os dados que vieram do Webhook
const webhookData = $('Webhook').first().json;

// Garante que pegamos a lista de clientes
const clientes = Array.isArray(webhookData.body) 
  ? webhookData.body 
  : (Array.isArray(webhookData) ? webhookData : [webhookData]);

// 2. Pega os investimentos do arquivo CSV
const investimentos = $input.all().map(item => item.json);

// 3. Função que atua como Consultor de Investimentos (gerando mensagens inteligentes)
function gerarMensagemConsultor(nome, perfil, saldo, produto, rentabilidade) {
  const primeiroNome = nome.split(' ')[0];

  if (perfil.toLowerCase() === 'conservador') {
    return `Olá, ${primeiroNome}! Analisamos seu momento financeiro e, com base no seu perfil Conservador e saldo de ${saldo}, priorizamos a máxima segurança e liquidez. Recomendamos aplicar em ${produto}, com retorno de ${rentabilidade}, garantindo proteção patrimonial e previsibilidade. Conte conosco para fazer seu dinheiro render com tranquilidade!`;
  } else if (perfil.toLowerCase() === 'moderado') {
    return `Olá, ${primeiroNome}! Seu perfil Moderado busca o equilíbrio ideal entre segurança e valorização do seu saldo disponível de ${saldo}. Indicamos o investimento em ${produto}, com rendimento de ${rentabilidade}, que potencializa seus ganhos sem abrir mão de estabilidade. Estamos à disposição para estruturar sua carteira!`;
  } else {
    return `Olá, ${primeiroNome}! Identificamos seu perfil Arrojado e sua prontidão para buscar as melhores oportunidades de rentabilidade com seu capital de ${saldo}. A nossa melhor recomendação para você é ${produto} (${rentabilidade}), permitindo capturar o potencial de alta dos mercados. Vamos juntos acelerar seu crescimento financeiro!`;
  }
}

// 4. Cruza os dados e monta a entrega final de cada cliente
return clientes.map(cliente => {
  // Encontra a melhor opção do CSV para o perfil
  const opcoes = investimentos.filter(
    inv => inv.perfil?.toLowerCase() === cliente.perfil?.toLowerCase()
  );

  const produtoMatch = opcoes.length > 0 ? opcoes[0] : { produto: 'Tesouro Direto', rentabilidade: '100% CDI' };

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      produto_recomendado: produtoMatch.produto,
      rentabilidade: produtoMatch.rentabilidade,
      mensagem_consultor: gerarMensagemConsultor(
        cliente.nome,
        cliente.perfil,
        cliente.saldo,
        produtoMatch.produto,
        produtoMatch.rentabilidade
      )
    }
  };
});

